function renderListaInterattiva(filter, page, cid){
    var _cache = flow.get('gs_cache');
    var _rows = (_cache && _cache.rows) ? _cache.rows : [];
    var _users = [];
    for(var _i=1; _i<_rows.length; _i++){
        if(!_rows[_i] || !_rows[_i][0]) continue;
        var _st = (_rows[_i][4] || 'attivo').toLowerCase().trim();
        if(_st !== filter) continue;
        _users.push(_rows[_i]);
    }
    var PER_PAGE = 15;
    var totalPages = Math.max(1, Math.ceil(_users.length / PER_PAGE));
    if(page < 0) page = 0;
    if(page > totalPages - 1) page = totalPages - 1;
    var pageUsers = _users.slice(page * PER_PAGE, page * PER_PAGE + PER_PAGE);
    var kb = [];
    pageUsers.forEach(function(u){
        var nm = ((u[1]||'') + ' ' + (u[2]||'')).trim() || (u[10] ? '@'+u[10] : u[0].toString());
        var eliteMark = u[5] === 'SI' ? '⭐ ' : '';
        var label = eliteMark + nm + ' (' + (u[3]||0) + ' 🎯)';
        if(label.length > 60) label = label.substring(0,57) + '...';
        kb.push([{text: label, callback_data: 'ADMIN_LISTA2_USER_' + u[0] + '_' + filter + '_' + page}]);
    });
    var navRow = [];
    if(page > 0) navRow.push({text:'◀️ Precedente', callback_data:'ADMIN_LISTA2_' + filter + '_' + (page-1)});
    if(page < totalPages - 1) navRow.push({text:'▶️ Successiva', callback_data:'ADMIN_LISTA2_' + filter + '_' + (page+1)});
    if(navRow.length) kb.push(navRow);
    kb.push([{text:'📄 Vedi come testo', callback_data:'ADMIN_LISTA2_TXT_' + filter}]);
    kb.push([{text:'⬅️ Indietro', callback_data:'ADMIN_LISTA_MENU'}]);
    kb.push([{text:'❌ Annulla', callback_data:'ADMIN_ANNULLA'}]);
    var title = _listaFilterLabel(filter);
    var body = _users.length === 0
        ? ('👥 *' + title + '* (0)\n\nNessun utente in questa categoria.')
        : ('👥 *' + title + '* (' + _users.length + ') — Pagina ' + (page+1) + '/' + totalPages + '\n\nTocca un utente per gestirlo:');
    return {chatId: cid, type: 'message', content: body, options: {parse_mode: 'Markdown', reply_markup: {inline_keyboard: kb}}};
}
