if(action==='ADMIN_REFERRAL_LISTA'){
    var _cacheR = flow.get('gs_cache');
    var _rowsR = (_cacheR && _cacheR.rows) ? _cacheR.rows : [];
    // Precalcola, per ogni invitante, quanti dei suoi invitati (colonna M) sono attivi/in pausa/scaduti ADESSO
    var _refBreakR = {};
    for(var _rb=1; _rb<_rowsR.length; _rb++){
        if(!_rowsR[_rb]||!_rowsR[_rb][0]) continue;
        var _invByR = (_rowsR[_rb][12]||'').toString().trim();
        if(!_invByR) continue;
        var _invStatusR = (_rowsR[_rb][4]||'attivo').toLowerCase().trim();
        if(!_refBreakR[_invByR]) _refBreakR[_invByR] = {attivo:0, pausa:0, scaduto:0};
        if(_invStatusR==='attivo') _refBreakR[_invByR].attivo++;
        else if(_invStatusR==='pausa') _refBreakR[_invByR].pausa++;
        else _refBreakR[_invByR].scaduto++;
    }
    var _list = [];
    for(var _ri=1; _ri<_rowsR.length; _ri++){
        var _row=_rowsR[_ri];
        if(!_row||!_row[0]) continue;
        var _cnt = parseInt(_row[13])||0;
        if(_cnt>0){
            var _nm = escapeMd(((_row[1]||'')+' '+(_row[2]||'')).trim()) || (_row[10]?'@'+_row[10]:_row[0]);
            var _bk = _refBreakR[(_row[0]||'').toString().trim()] || {attivo:0,pausa:0,scaduto:0};
            _list.push({name:_nm, id:_row[0], count:_cnt, attivo:_bk.attivo, pausa:_bk.pausa, scaduto:_bk.scaduto});
        }
    }
    _list.sort(function(a,b){return b.count-a.count;});
    if(_list.length===0){
        msg.payload={chatId:chatId,type:'message',content:'👥 *CLASSIFICA REFERRAL*\n\nNessun invito confermato ancora.',options:{parse_mode:'Markdown'}};
        return[msg,null];
    }
    var _txt='👥 *CLASSIFICA REFERRAL*\n\n';
    for(var _li=0; _li<_list.length; _li++){
        _txt += (_li+1)+'. '+_list[_li].name+' — 🎯 *'+_list[_li].count+'* inviti totali (ID: '+_list[_li].id+')\n';
        _txt += '   🟢 '+_list[_li].attivo+' attivi · ⏸ '+_list[_li].pausa+' pausa · 🔴 '+_list[_li].scaduto+' scaduti\n';
    }
    msg.payload={chatId:chatId,type:'message',content:_txt,options:{parse_mode:'Markdown'}};
    return[msg,null];
}
