function freeBtnFixedLabel(key){
    var labels={attivagratis:'⚡ Attiva Bot Gratis', comefunziona:'🤖 Come Funziona', promo:'🎉 Promo Attive', metodo:'🎯 Metodo Gioco', book:'📈 BOOK', bilancio:'📊 BILANCIO'};
