function buildFreeMenuKeyboard(){
    var enabledMap = flow.get('free_menu_fixed_enabled') || {};
    var rowsMap = {};
    FREEBTN_FIXED_DEFS.forEach(function(b){
        if(enabledMap[b.key]===false) return;
        rowsMap[b.row]=rowsMap[b.row]||[];
        if(b.key==='comefunziona' || b.key==='metodo'){
            var _varPrefix = (b.key==='comefunziona') ? 'come_funziona' : 'metodo';
            var _t=flow.get(_varPrefix+'_type');
            var _lk=flow.get(_varPrefix+'_link');
            if(_t==='link' && _lk){ rowsMap[b.row].push({text:b.label, url:_lk}); return; }
        }
        rowsMap[b.row].push({text:b.label, callback_data:'FREEQ_'+b.key});
    });
    var kb = Object.keys(rowsMap).sort(function(a,b){return a-b;}).map(function(r){return rowsMap[r];});
    var customBtns = flow.get('free_menu_custom_buttons') || [];
    customBtns.forEach(function(b,i){
        if(b.enabled===false) return;
        if(b.type==='link'){ kb.push([{text:b.label, url:b.link}]); }
        else { kb.push([{text:b.label, callback_data:'FREEQC_'+i}]); }
    });
    kb.push([{text:'🆘 ASSISTENZA', callback_data:'FREEQ_assistenza'}]);
    return kb;
}
