function renderFreeTimingMenu(cid){
    var interval = flow.get('free_menu_interval_hours');
    if(interval===undefined||interval===null) interval=2;
    var startH = flow.get('free_menu_start_hour');
    if(startH===undefined||startH===null) startH=8;
    var endH = flow.get('free_menu_end_hour');
    if(endH===undefined||endH===null) endH=22;
    var enabled = flow.get('free_menu_auto_enabled') !== false;
    var hours=[];
    for(var h=startH; h<=endH; h+=interval){ hours.push(h); }
    var hoursStr = hours.map(function(h){return (h<10?'0':'')+h+':00';}).join(', ');
    var toggleBtn = enabled
        ? {text:'🔴 Disattiva invio automatico', callback_data:'ADMIN_FREETIME_OFF'}
        : {text:'🟢 Attiva invio automatico', callback_data:'ADMIN_FREETIME_ON'};
    return {chatId:cid, type:'message',
        content:'⏱ *ORARIO INVIO AUTOMATICO — MENU GRUPPO FREE*\n\n📊 Stato: '+(enabled?'🟢 Attivo':'🔴 Disattivato')+'\n🔁 Ogni: *'+interval+' ore*\n🕐 Dalle *'+startH+':00* alle *'+endH+':00*\n📋 Orari di invio: '+hoursStr,
        options:{parse_mode:'Markdown', reply_markup:{inline_keyboard:[
            [toggleBtn],
            [{text:'🔁 Cambia Intervallo (ore)', callback_data:'ADMIN_FREETIME_INTERVAL'}],
            [{text:'🕐 Cambia Ora Inizio', callback_data:'ADMIN_FREETIME_START'},{text:'🕙 Cambia Ora Fine', callback_data:'ADMIN_FREETIME_END'}],
            [{text:'⬅️ Indietro', callback_data:'ADMIN_GRUPPO_FREE_MENU'}],
            [{text:'❌ Annulla', callback_data:'ADMIN_ANNULLA'}]
        ]}}};
}
