if (!waiting) return null;

// Foto/file gestiti da '📸 Gestisci File Ricevuta' — qui solo testo
if (msg.payload.type && msg.payload.type !== 'message') return null;

var input = msg.payload.content;
var chatId = msg.payload.chatId;

if (!input || input.startsWith('/')) { flow.set('admin_waiting', null); return null; }

// Se l'admin digita un numero puro (es. 1, 2) lo trattiamo come #N della lista
// SOLO per azioni su utenti (non per quantità segnali)
var isUserAction = (waiting.action === 'elite' || waiting.action === 'togli_elite'
    || waiting.action === 'approva' || waiting.action === 'rifiuta'
    || waiting.action === 'segnali_id');
if (isUserAction && /^\d+$/.test(input.trim()) && parseInt(input.trim()) < 10000) {
    input = '#' + input.trim();
}

if (waiting.action === 'elite') {
    flow.set('admin_waiting', null);
    msg.chatId = chatId; msg.userId = adminId;
    msg.targetUserId = input.trim(); msg.action = 'elite';
    return [null, msg];
}
