if (waiting.action === 'segnali_id') {
    var cache = flow.get('gs_cache');
    var rows = (cache && cache.rows) ? cache.rows : [];
    var searchStr = input.trim().replace(/^@/,'').toLowerCase();
    var foundName = '', foundUser = '', foundId = '';
    if (input.trim().charAt(0) === '#') {
        var listN = parseInt(input.trim().substring(1));
        var cnt = 0;
        for (var ri=1;ri<rows.length;ri++) {
            if (!rows[ri]||!rows[ri][0]) continue;
            cnt++;
            if (cnt === listN) {
                foundName = ((rows[ri][1]||'')+' '+(rows[ri][2]||'')).trim();
                foundUser = rows[ri][10] ? '@'+rows[ri][10] : '';
                foundId = rows[ri][0].toString();
                break;
            }
        }
    } else {
        for (var ri=1;ri<rows.length;ri++) {
            if (!rows[ri]||!rows[ri][0]) continue;
            if (rows[ri][0].toString()===searchStr) {
                foundName=((rows[ri][1]||'')+' '+(rows[ri][2]||'')).trim();
                foundUser=rows[ri][10]?'@'+rows[ri][10]:'';
                foundId=rows[ri][0].toString();
                break;
            }
            var ru=(rows[ri][10]||'').replace(/^@/,'').toLowerCase();
            if (ru && ru===searchStr) {
                foundName=((rows[ri][1]||'')+' '+(rows[ri][2]||'')).trim();
                foundUser=rows[ri][10]?'@'+rows[ri][10]:'';
                foundId=rows[ri][0].toString();
                break;
            }
            var fn=((rows[ri][1]||'')+' '+(rows[ri][2]||'')).trim().toLowerCase();
            if (fn && fn===searchStr) {
                foundName=((rows[ri][1]||'')+' '+(rows[ri][2]||'')).trim();
                foundUser=rows[ri][10]?'@'+rows[ri][10]:'';
                foundId=rows[ri][0].toString();
                break;
            }
        }
    }
    var userLine = foundName ? '\n\ud83d\udc64 *'+foundName+'*' : '';
    userLine += foundUser ? '  '+foundUser : '';
